func:
flow.set('ultimo', msg.payload);
return [
  { payload: msg.payload.temperatura },
  { payload: msg.payload.humedad },
  { payload: msg.payload.luz_pct },
  { payload: msg.payload.calidad_aire_pct },
  { payload: msg.payload.alarma }
];

if (msg.payload === "online") {
    msg.payload = "🟢 ESP32 CONECTADO A INTERNET";
} else {
    msg.payload = "🔴 ESP32 DESCONECTADO";
}
return msg;

// ===== AJUSTES DEL MODO AUTOMÁTICO (puedes cambiarlos) =====
const CFG = {sp: 48.0, kp: 15, ki: 0.05, kd: 5};
// ============================================================
flow.set('cfg', CFG);

let d = msg.payload;
if (typeof d === 'string') {
    try { d = JSON.parse(d); }
    catch (e) { node.warn('Telemetría JSON inválida'); return null; }
}
if (!d || typeof d !== 'object') return null;

const c = Number(d.codigo_falla || 0);
const timeout = (c & 8) !== 0;
flow.set('falla_timeout', timeout);

// Un sensor se considera malo por el bit de falla O por lectura inválida en vivo
// (igual que el OLED del ESP32). Con timeout de llenado se oculta el aviso de sensores.
const tempMal = (c & 1) !== 0 || d.temp_valida === false;
const nivelMal = (c & 2) !== 0 || d.nivel_valida === false;
const f = [];
if (!timeout && tempMal) f.push('Sensor de temperatura inválido');
if (!timeout && nivelMal) f.push('Sensor de nivel sin lectura válida');
if (c & 4) f.push('Sobretemperatura del pulmón');
if (c & 8) f.push('Timeout de llenado');
if (c & 16) f.push('Sobretemperatura del encamisado');
d.fallas_txt = f.join(', ');
d.offline = false;

// Alerta de nivel generada aquí en Node-RED (el ESP32 no la envía por MQTT).
// Se emite al pasar de nivel bueno a malo, máximo 1 vez cada 30 s.
const alertas = [];      // avisos que se muestran en el dashboard
const cmdsGuard = [];    // comandos de seguridad hacia el ESP32
const prevMal = flow.get('nivel_mal_prev') === true;
flow.set('nivel_mal_prev', nivelMal);
if (nivelMal && !prevMal && !timeout) {
    const ahoraA = Date.now();
    if (ahoraA - (context.get('ult_alerta_nivel') || 0) > 30000) {
        context.set('ult_alerta_nivel', ahoraA);
        alertas.push({payload: new Date().toLocaleTimeString('es-CO') + ' · SENSOR_NIVEL_INVALIDO: Sensor de nivel sin lectura válida'});
    }
}

// El ESP32 no informa qué botones se pidieron: Node-RED lo recuerda
flow.set('modo_manual', d.modo_manual === true);
let man = flow.get('man') || {bomba:false, valvula:false, niquelina:false, agitador:false};
if (!d.modo_manual) {
    man = {bomba:false, valvula:false, niquelina:false, agitador:false};
    flow.set('man', man);
}
// Seguridad de proceso en manual: la niquelina no puede quedar pedida con el pulmón
// en o por encima del setpoint. Se apaga el pedido, se envía OFF y se avisa.
if (d.modo_manual && man.niquelina && d.temp_valida === true &&
    Number(d.temp_pulmon) >= Number(d.setpoint)) {
    man.niquelina = false;
    flow.set('man', man);
    cmdsGuard.push({payload: {cmd: 'niquelina', valor: false}});
    alertas.push({payload: new Date().toLocaleTimeString('es-CO') + ' · NIQUELINA_APAGADA: pulmón a ' +
        Number(d.temp_pulmon).toFixed(1) + ' °C alcanzó el setpoint (' + Number(d.setpoint).toFixed(1) + ' °C)'});
}
d.man_bomba = man.bomba;
d.man_valvula = man.valvula;
d.man_niquelina = man.niquelina;
d.man_agitador = man.agitador;

// ---- Motivo por el que un equipo pedido en manual NO enciende (vacío = sin impedimento)
const num = x => Number(x);
const T = d.temp_valida === true, Nv = d.nivel_valida === true;
const cok = d.cargas_ok;   // true/false; undefined si el ESP32 es de la versión anterior
const est = d.estado;
const pul = num(d.temp_pulmon), enc = num(d.temp_encamisado), niv = num(d.nivel_cm), sp = num(d.setpoint);
const lim = sp + 4;
const comun = () => {
    if (est === 'FALLA') return 'Sistema en FALLA: rearme primero';
    if (!T) return 'Sensores de temperatura sin lectura válida';
    if (!Nv) return 'Sensor de nivel sin lectura válida';
    return '';
};
const motivo = {bomba: '', valvula: '', niquelina: '', agitador: ''};
if (d.modo_manual) {
    if (man.bomba) {
        motivo.bomba = comun()
            || (est !== 'NORMAL' ? 'Estado ' + est + ': la bomba solo funciona en NORMAL' : '')
            || (niv > 4 ? 'Nivel bajo (' + niv.toFixed(1) + ' cm; debe ser 4 cm o menos)' : '')
            || (cok === false ? 'Nivel sin confirmar (necesita 5 lecturas estables de 4 cm o menos)' : '')
            || (pul < 36 ? 'Pulmón a ' + pul.toFixed(1) + ' °C (mínimo 36 °C)' : '')
            || (d.valvula ? 'Válvula abierta' : '')
            || (num(d.velocidad_bomba) <= 0 ? 'Velocidad de bomba en 0 %' : '');
        if (d.bomba) motivo.bomba = '';
    }
    if (man.niquelina) {
        motivo.niquelina = comun()
            || (est !== 'NORMAL' ? 'Estado ' + est + ': la niquelina solo funciona en NORMAL' : '')
            || (niv > 4 ? 'Nivel bajo (' + niv.toFixed(1) + ' cm; debe ser 4 cm o menos)' : '')
            || (cok === false ? 'Nivel sin confirmar (necesita 5 lecturas estables de 4 cm o menos)' : '')
            || (d.valvula ? 'Válvula abierta' : '')
            || ((pul >= lim || enc >= lim) ? 'Temperatura sobre el límite (' + lim.toFixed(0) + ' °C)' : '');
        if (d.niquelina) motivo.niquelina = '';
    }
    if (man.valvula) {
        motivo.valvula = comun()
            || (c !== 0 ? 'Hay una falla activa' : '')
            || (niv <= 3 ? 'Nivel alcanzado (' + niv.toFixed(1) + ' cm; ya está lleno)' : '')
            || ((pul >= lim || enc >= lim) ? 'Temperatura sobre el límite (' + lim.toFixed(0) + ' °C)' : '');
        if (d.valvula) motivo.valvula = '';
    }
    if (man.agitador) {
        motivo.agitador = (est === 'FALLA' ? 'Sistema en FALLA: rearme primero' : '')
            || (est === 'INIT' ? 'Estado INIT: faltan lecturas o el nivel no está confirmado' : '')
            || (!T ? 'Sensores de temperatura sin lectura válida' : '')
            || (!d.agitador && enc < 30 ? 'Encamisado a ' + enc.toFixed(1) + ' °C (enciende desde 30 °C)' : '');
        if (d.agitador) motivo.agitador = '';
    }
}
d.bloq_bomba = motivo.bomba;
d.bloq_valvula = motivo.valvula;
d.bloq_niquelina = motivo.niquelina;
d.bloq_agitador = motivo.agitador;

// Se guarda el último dato completo para mostrarlo si se pierde la comunicación
flow.set('ultimo_d', JSON.parse(JSON.stringify(d)));

// Si un sensor no tiene lectura válida (el ESP32 manda 0), se conserva la última lectura buena
const guardado = flow.get('ultimas_temps') || {};
if (Number(d.temp_pulmon) > 0) guardado.p = Number(d.temp_pulmon);
if (Number(d.temp_encamisado) > 0) guardado.e = Number(d.temp_encamisado);
if (d.nivel_valida === true && Number(d.nivel_cm) > 0) guardado.n = Number(d.nivel_cm);
flow.set('ultimas_temps', guardado);

// Guardián: en automático el setpoint es siempre CFG.sp y el PID usa CFG
let cmds = null;
if (!d.modo_manual) {
    const ahora = Date.now();
    if (ahora - (context.get('ult') || 0) > 5000) {
        const out = [];
        if (Math.abs(Number(d.setpoint) - CFG.sp) > 0.05) {
            out.push({payload: {cmd: 'setpoint', valor: CFG.sp}});
        }
        if (Math.abs(Number(d.kp) - CFG.kp) > 0.006 ||
            Math.abs(Number(d.ki) - CFG.ki) > 0.006 ||
            Math.abs(Number(d.kd) - CFG.kd) > 0.006) {
            out.push({payload: {cmd: 'pid', kp: CFG.kp, ki: CFG.ki, kd: CFG.kd}});
        }
        if (out.length) { context.set('ult', ahora); cmds = out; }
    }
}

// Tras una caída de más de 60 s los botones se apagaron en pantalla; al volver la
// comunicación se apagan también los pedidos manuales que hayan quedado en el ESP32.
if (flow.get('resync') === true) {
    flow.set('resync', false);
    if (d.modo_manual) {
        const off = ['bomba', 'valvula', 'niquelina', 'agitador']
            .map(k => ({payload: {cmd: k, valor: false}}));
        cmds = (cmds || []).concat(off);
    }
}

if (cmdsGuard.length) cmds = (cmds || []).concat(cmdsGuard);

return [
  {payload: guardado.p !== undefined ? guardado.p : 0},
  {payload: guardado.e !== undefined ? guardado.e : 0},
  {payload: guardado.n !== undefined ? guardado.n : 0},
  {payload: Number(d.pid_pct || 0)},
  {payload: d},
  cmds,
  alertas.length ? alertas : null
];

// 30 s sin telemetría: banner de sin conexión y panel atenuado (los medidores se conservan)
const ultimo = flow.get('ultimo_d') || {};
const d = Object.assign({}, ultimo, {offline: true, estado: 'SIN CONEXIÓN', fallas_txt: ''});
return [null, null, null, null, {payload: d}];

let a = msg.payload;
if (typeof a === 'string') { try { a = JSON.parse(a); } catch (e) { a = {mensaje: a}; } }
a = a || {};
const tipo = a.tipo || 'ALERTA';

// Solo se muestran estas alertas
const permitidas = [
    'SENSOR_TEMP_INVALIDO',
    'SOBRETEMPERATURA',
    'SOBRETEMPERATURA_ENCAMISADO',
    'NIVEL_BAJO',
    'TIMEOUT_LLENADO',
    'COMANDO_INVALIDO',
    'REARME_SOLICITADO',
    'REARME_RECHAZADO'
];
if (!permitidas.includes(tipo)) return null;

// Con falla por timeout de llenado no se muestra el aviso de sensor de temperatura
if (tipo === 'SENSOR_TEMP_INVALIDO' && flow.get('falla_timeout') === true) return null;

// NIVEL_BAJO se muestra como máximo 1 vez cada 2 minutos
if (tipo === 'NIVEL_BAJO') {
    const ult = context.get('ult') || 0;
    const ahora = Date.now();
    if (ahora - ult < 120000) return null;
    context.set('ult', ahora);
}

const hora = new Date().toLocaleTimeString('es-CO');
msg.payload = hora + ' · ' + tipo + ': ' + (a.mensaje || '');
return msg;

const c = msg.payload;
if (!c || typeof c !== 'object') return null;

const cfg = flow.get('cfg') || {sp: 48, kp: 15, ki: 0.05, kd: 5};
const manual = flow.get('modo_manual') === true;
const vacio = {bomba:false, valvula:false, niquelina:false, agitador:false};
const m = x => ({payload: x});
// Salida 1: comandos hacia el ESP32.  Salida 2: avisos al dashboard.

if (c.cmd === 'modo') {
    flow.set('man', Object.assign({}, vacio));
    if (c.valor === 'manual') {
        // Entra a manual con todo apagado
        return [[m({cmd:'bomba', valor:false}), m({cmd:'valvula', valor:false}),
                 m({cmd:'niquelina', valor:false}), m({cmd:'agitador', valor:false}), m(c)], null];
    }
    // Automático: modo + setpoint fijo + PID suave
    return [[m(c), m({cmd:'setpoint', valor:cfg.sp}),
             m({cmd:'pid', kp:cfg.kp, ki:cfg.ki, kd:cfg.kd})], null];
}

if (['bomba', 'valvula', 'niquelina', 'agitador'].includes(c.cmd)) {
    if (!manual) return null;          // solo se accionan en modo manual

    // La niquelina no se enciende si el pulmón ya está en o sobre el setpoint
    if (c.cmd === 'niquelina' && c.valor === true) {
        const u = flow.get('ultimo_d') || {};
        const pul = Number(u.temp_pulmon), sp = Number(u.setpoint);
        if (u.temp_valida === true && Number.isFinite(pul) && Number.isFinite(sp) && pul >= sp) {
            const hora = new Date().toLocaleTimeString('es-CO');
            return [null, m(hora + ' · NIQUELINA_BLOQUEADA: pulmón a ' + pul.toFixed(1) +
                ' °C, por encima del setpoint (' + sp.toFixed(1) + ' °C)')];
        }
    }

    const man = flow.get('man') || Object.assign({}, vacio);
    man[c.cmd] = c.valor === true;
    flow.set('man', man);
    return [m(c), null];
}

if (c.cmd === 'setpoint') return manual ? [m(c), null] : null;   // en automático es fijo

return [m(c), null];

const n = Number(msg.payload);
if (!Number.isFinite(n)) return null;
msg.payload = {cmd:'setpoint', valor:n};
return msg;

const n = Number(msg.payload);
if (!Number.isFinite(n)) return null;
msg.payload = {cmd:'velocidad_bomba', valor:n};
return msg;

let p = msg.payload;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch(e) { node.warn('Comando JSON inválido'); return null; } }
if (!p || typeof p !== 'object') return null;
msg.topic = 'choco_tanque/comandos';
msg.payload = JSON.stringify(p);
return msg;

// 60 s sin telemetría: medidores a 0, botones apagados y pedidos manuales en OFF
const vacio = {bomba:false, valvula:false, niquelina:false, agitador:false};
flow.set('man', Object.assign({}, vacio));
flow.set('modo_manual', false);
flow.set('resync', true);   // al volver la comunicación se re-sincroniza el ESP32

const ultimo = flow.get('ultimo_d') || {};
const d = Object.assign({}, ultimo, {
    offline: true,
    controles_apagados: true,
    estado: 'SIN CONEXIÓN',
    fallas_txt: '',
    modo_manual: null,   // ningún botón de modo queda en verde
    man_bomba: false, man_valvula: false, man_niquelina: false, man_agitador: false,
    bloq_bomba: '', bloq_valvula: '', bloq_niquelina: '', bloq_agitador: ''
});
flow.set('ultimo_d', d);

// Mejor esfuerzo: pedir OFF a los equipos manuales (si el ESP32 aún recibe comandos)
const off = ['bomba', 'valvula', 'niquelina', 'agitador']
    .map(k => ({payload: {cmd: k, valor: false}}));

return [{payload: 0}, {payload: 0}, {payload: 0}, {payload: 0}, {payload: d}, off];
